{-| @Backend.Runtime.Kernel.Xml — the XML reader over `Std.Xml.Tag` boxes. -}
module Pudu.Backend.Runtime.Kernel.Xml (xmlKernelParts) where

import Data.Text (Text)

{-| Each part: its name, the parts it needs, and its lines. -}
xmlKernelParts :: [(Text, [Text], [Text])]
xmlKernelParts =
  [ ("xml_reader", ["array", "array_reserve", "text_allocate"],
      [ "/* A document and where the Tag fields and Node variants sit. A reader walks"
      , "   the document twice: once to accept it, once to build. */"
      , "typedef struct { const unsigned char *bytes; size_t size; int name_at, attributes_at, children_at, element_tag, content_tag; } pudu_xml;"
      , "static int pudu_xml_blank(unsigned char byte) { return byte == 32 || byte == 9 || byte == 10 || byte == 13; }"
      , "static size_t pudu_xml_space(const pudu_xml *in, size_t at) {"
      , "  while (at < in->size && pudu_xml_blank(in->bytes[at])) at += 1;"
      , "  return at;"
      , "}"
      , "/* The end of a name: anything but whitespace and < > / = \" ' ? ! */"
      , "static size_t pudu_xml_name(const pudu_xml *in, size_t at) {"
      , "  while (at < in->size && !pudu_xml_blank(in->bytes[at]) && strchr(\"<>/=\\\"'?!\", in->bytes[at]) == NULL) at += 1;"
      , "  return at;"
      , "}"
      , "static int pudu_xml_starts(const pudu_xml *in, size_t at, const char *marker) {"
      , "  size_t length = strlen(marker);"
      , "  return at <= in->size && in->size - at >= length && memcmp(in->bytes + at, marker, length) == 0;"
      , "}"
      , "/* The position just past the first marker at or after a position, or 0. */"
      , "static size_t pudu_xml_past(const pudu_xml *in, size_t at, const char *marker) {"
      , "  size_t length = strlen(marker);"
      , "  for (; at <= in->size && in->size - at >= length; ++at)"
      , "    if (memcmp(in->bytes + at, marker, length) == 0) return at + length;"
      , "  return 0;"
      , "}"
      , "/* One scalar of valid UTF-8 and its width. */"
      , "static uint32_t pudu_xml_scalar(const unsigned char *at, size_t *width) {"
      , "  if (at[0] < 0x80) { *width = 1; return at[0]; }"
      , "  if (at[0] < 0xE0) { *width = 2; return ((uint32_t)(at[0] & 0x1F) << 6) | (at[1] & 0x3F); }"
      , "  if (at[0] < 0xF0) { *width = 3; return ((uint32_t)(at[0] & 0x0F) << 12) | ((uint32_t)(at[1] & 0x3F) << 6) | (at[2] & 0x3F); }"
      , "  *width = 4;"
      , "  return ((uint32_t)(at[0] & 0x07) << 18) | ((uint32_t)(at[1] & 0x3F) << 12) | ((uint32_t)(at[2] & 0x3F) << 6) | (at[3] & 0x3F);"
      , "}"
      , "/* Whether every character is one the reference counts as space. */"
      , "static int pudu_xml_spaces(const unsigned char *bytes, size_t length) {"
      , "  for (size_t at = 0, width; at < length; at += width) {"
      , "    uint32_t scalar = pudu_xml_scalar(bytes + at, &width);"
      , "    if (scalar == 32 || (scalar >= 9 && scalar <= 13) || scalar == 0xA0 || scalar == 0x1680"
      , "        || (scalar >= 0x2000 && scalar <= 0x200A) || scalar == 0x202F || scalar == 0x205F || scalar == 0x3000) continue;"
      , "    return 0;"
      , "  }"
      , "  return 1;"
      , "}"
      , "/* Text with entities decoded: the five named ones and numeric references."
      , "   An & whose ; is not among the next twelve characters stays, as does an"
      , "   entity nothing defines; a reference naming no scalar is dropped. Writes"
      , "   into out when it is there and answers the length. */"
      , "static size_t pudu_xml_unescape(const unsigned char *bytes, size_t length, unsigned char *out) {"
      , "  size_t written = 0, at = 0;"
      , "  while (at < length) {"
      , "    size_t end = at + 1, seen = 0, width, digits;"
      , "    uint64_t code = 0;"
      , "    int base = 10, known = 1;"
      , "    if (bytes[at] != '&') {"
      , "      if (out != NULL) out[written] = bytes[at];"
      , "      written += 1;"
      , "      at += 1;"
      , "      continue;"
      , "    }"
      , "    while (end < length && seen < 12 && bytes[end] != ';') { (void)pudu_xml_scalar(bytes + end, &width); end += width; seen += 1; }"
      , "    if (end >= length || seen >= 12) {"
      , "      if (out != NULL) out[written] = '&';"
      , "      written += 1;"
      , "      at += 1;"
      , "      continue;"
      , "    }"
      , "#define PUDU_XML_NAMED(word, byte) (end - at - 1 == strlen(word) && memcmp(bytes + at + 1, word, strlen(word)) == 0) { if (out != NULL) out[written] = byte; written += 1; }"
      , "    if PUDU_XML_NAMED(\"lt\", '<')"
      , "    else if PUDU_XML_NAMED(\"gt\", '>')"
      , "    else if PUDU_XML_NAMED(\"amp\", '&')"
      , "    else if PUDU_XML_NAMED(\"quot\", '\"')"
      , "    else if PUDU_XML_NAMED(\"apos\", '\\'')"
      , "    else {"
      , "      digits = at + 2;"
      , "      known = end - at - 1 >= 1 && bytes[at + 1] == '#';"
      , "      if (known && digits < end && (bytes[digits] == 'x' || bytes[digits] == 'X')) { base = 16; digits += 1; }"
      , "      if (digits >= end) known = 0;"
      , "      for (size_t i = digits; known && i < end; ++i) {"
      , "        unsigned char byte = bytes[i];"
      , "        int digit = byte >= '0' && byte <= '9' ? byte - '0' : byte >= 'a' && byte <= 'f' ? byte - 'a' + 10 : byte >= 'A' && byte <= 'F' ? byte - 'A' + 10 : 99;"
      , "        if (digit >= base) known = 0;"
      , "        else code = code * (uint64_t)base + (uint64_t)digit;"
      , "      }"
      , "      if (!known) {"
      , "        if (out != NULL) memcpy(out + written, bytes + at, end - at + 1);"
      , "        written += end - at + 1;"
      , "      } else if (code <= 0x10FFFF && !(code >= 0xD800 && code <= 0xDFFF)) {"
      , "        if (code < 0x80) {"
      , "          if (out != NULL) out[written] = (unsigned char)code;"
      , "          written += 1;"
      , "        } else if (code < 0x800) {"
      , "          if (out != NULL) { out[written] = (unsigned char)(0xC0 | (code >> 6)); out[written + 1] = (unsigned char)(0x80 | (code & 0x3F)); }"
      , "          written += 2;"
      , "        } else if (code < 0x10000) {"
      , "          if (out != NULL) {"
      , "            out[written] = (unsigned char)(0xE0 | (code >> 12));"
      , "            out[written + 1] = (unsigned char)(0x80 | ((code >> 6) & 0x3F));"
      , "            out[written + 2] = (unsigned char)(0x80 | (code & 0x3F));"
      , "          }"
      , "          written += 3;"
      , "        } else {"
      , "          if (out != NULL) {"
      , "            out[written] = (unsigned char)(0xF0 | (code >> 18));"
      , "            out[written + 1] = (unsigned char)(0x80 | ((code >> 12) & 0x3F));"
      , "            out[written + 2] = (unsigned char)(0x80 | ((code >> 6) & 0x3F));"
      , "            out[written + 3] = (unsigned char)(0x80 | (code & 0x3F));"
      , "          }"
      , "          written += 4;"
      , "        }"
      , "      }"
      , "    }"
      , "#undef PUDU_XML_NAMED"
      , "    at = end + 1;"
      , "  }"
      , "  return written;"
      , "}"
      , "/* A span as owned text, decoded when asked. */"
      , "static pudu_text pudu_xml_text(const pudu_xml *in, size_t from, size_t to, int decode) {"
      , "  unsigned char *bytes;"
      , "  pudu_text text = pudu_text_allocate(decode ? pudu_xml_unescape(in->bytes + from, to - from, NULL) : to - from, &bytes);"
      , "  if (decode) (void)pudu_xml_unescape(in->bytes + from, to - from, bytes);"
      , "  else if (to != from) memcpy(bytes, in->bytes + from, to - from);"
      , "  return text;"
      , "}"
      , "static void pudu_xml_push(pudu_box *array, pudu_box *member) {"
      , "  pudu_array_reserve(array, pudu_array_length(array) + 1);"
      , "  array->fields[0].items->cells[pudu_array_length(array)].box = member;"
      , "  pudu_array_length(array) += 1;"
      , "}"
      , "static void pudu_xml_content(const pudu_xml *in, pudu_box *children, size_t from, size_t to, int decode) {"
      , "  pudu_box *node = pudu_box_new(2);"
      , "  node->fields[0].scalar = in->content_tag;"
      , "  node->fields[1].text = pudu_xml_text(in, from, to, decode);"
      , "  pudu_xml_push(children, node);"
      , "}"
      , "/* The element opening at a position. With made absent the document is only checked. */"
      , "static int pudu_xml_element(const pudu_xml *in, size_t from, int depth, pudu_box **made, size_t *next) {"
      , "  size_t name_end, at, first;"
      , "  pudu_box *attributes = NULL, *children = NULL;"
      , "  if (from >= in->size || in->bytes[from] != '<') return 0;"
      , "  name_end = pudu_xml_name(in, from + 1);"
      , "  if (name_end == from + 1) return 0;"
      , "  if (made != NULL) {"
      , "    *made = pudu_box_new(3);"
      , "    attributes = pudu_array_new(0);"
      , "    children = pudu_array_new(0);"
      , "    (*made)->fields[in->name_at].text = pudu_xml_text(in, from + 1, name_end, 0);"
      , "    (*made)->fields[in->attributes_at].box = attributes;"
      , "    (*made)->fields[in->children_at].box = children;"
      , "  }"
      , "  first = at = name_end;"
      , "  for (;;) {"
      , "    size_t here = pudu_xml_space(in, at), end, equals, open, close;"
      , "    if (here >= in->size) return 0;"
      , "    if (in->bytes[here] == '/') {"
      , "      if (here + 1 >= in->size || in->bytes[here + 1] != '>') return 0;"
      , "      *next = here + 2;"
      , "      return 1;"
      , "    }"
      , "    if (in->bytes[here] == '>') { at = here + 1; break; }"
      , "    end = pudu_xml_name(in, here);"
      , "    if (end == here) return 0;"
      , "    /* A repeated attribute name is left to the library's reader. */"
      , "    for (size_t seen = first;;) {"
      , "      size_t start = pudu_xml_space(in, seen), stop = pudu_xml_name(in, start), quote;"
      , "      if (start >= here) break;"
      , "      if (stop - start == end - here && memcmp(in->bytes + start, in->bytes + here, end - here) == 0) return 0;"
      , "      quote = pudu_xml_space(in, pudu_xml_space(in, stop) + 1);"
      , "      seen = quote + 1;"
      , "      while (in->bytes[seen] != in->bytes[quote]) seen += 1;"
      , "      seen += 1;"
      , "    }"
      , "    equals = pudu_xml_space(in, end);"
      , "    if (equals >= in->size || in->bytes[equals] != '=') return 0;"
      , "    open = pudu_xml_space(in, equals + 1);"
      , "    if (open >= in->size || (in->bytes[open] != '\"' && in->bytes[open] != '\\'')) return 0;"
      , "    for (close = open + 1; close < in->size && in->bytes[close] != in->bytes[open];) close += 1;"
      , "    if (close >= in->size) return 0;"
      , "    if (made != NULL) {"
      , "      pudu_box *pair = pudu_box_new(2);"
      , "      pair->fields[0].text = pudu_xml_text(in, here, end, 0);"
      , "      pair->fields[1].text = pudu_xml_text(in, open + 1, close, 1);"
      , "      pudu_xml_push(attributes, pair);"
      , "    }"
      , "    at = close + 1;"
      , "  }"
      , "  for (;;) {"
      , "    if (at >= in->size) return 0;"
      , "    if (pudu_xml_starts(in, at, \"</\")) {"
      , "      size_t close_end = pudu_xml_name(in, at + 2), after = pudu_xml_space(in, close_end);"
      , "      if (close_end - (at + 2) != name_end - (from + 1) || memcmp(in->bytes + at + 2, in->bytes + from + 1, name_end - (from + 1)) != 0) return 0;"
      , "      if (after >= in->size || in->bytes[after] != '>') return 0;"
      , "      *next = after + 1;"
      , "      return 1;"
      , "    }"
      , "    if (pudu_xml_starts(in, at, \"<!--\")) { at = pudu_xml_past(in, at, \"-->\"); if (at == 0) return 0; continue; }"
      , "    if (pudu_xml_starts(in, at, \"<![CDATA[\")) {"
      , "      size_t end = pudu_xml_past(in, at, \"]]>\");"
      , "      if (end == 0) return 0;"
      , "      if (made != NULL) pudu_xml_content(in, children, at + 9, end - 3, 0);"
      , "      at = end;"
      , "      continue;"
      , "    }"
      , "    if (pudu_xml_starts(in, at, \"<?\")) { at = pudu_xml_past(in, at, \"?>\"); if (at == 0) return 0; continue; }"
      , "    if (in->bytes[at] == '<') {"
      , "      pudu_box *nested = NULL, *node;"
      , "      if (depth >= 512 || !pudu_xml_element(in, at, depth + 1, made == NULL ? NULL : &nested, &at)) return 0;"
      , "      if (made != NULL) {"
      , "        node = pudu_box_new(2);"
      , "        node->fields[0].scalar = in->element_tag;"
      , "        node->fields[1].box = nested;"
      , "        pudu_xml_push(children, node);"
      , "      }"
      , "      continue;"
      , "    }"
      , "    {"
      , "      size_t end = at;"
      , "      while (end < in->size && in->bytes[end] != '<') end += 1;"
      , "      if (made != NULL && !pudu_xml_spaces(in->bytes + at, end - at)) pudu_xml_content(in, children, at, end, 1);"
      , "      at = end;"
      , "    }"
      , "  }"
      , "}"
      ])
  , ("xml_decode", ["xml_reader"],
      [ "/* The root element after declarations, instructions and comments, or no"
      , "   box. A document type declaration is not read. */"
      , "static pudu_box *pudu_xml_decode(pudu_text source, int name_at, int attributes_at, int children_at, int element_tag, int content_tag) {"
      , "  pudu_xml in = {source.bytes, source.length, name_at, attributes_at, children_at, element_tag, content_tag};"
      , "  size_t at = 0, next = 0;"
      , "  pudu_box *made = NULL;"
      , "  for (;;) {"
      , "    at = pudu_xml_space(&in, at);"
      , "    if (at + 1 >= in.size || in.bytes[at] != '<') break;"
      , "    if (in.bytes[at + 1] == '?') at = pudu_xml_past(&in, at, \"?>\");"
      , "    else if (in.bytes[at + 1] != '!') break;"
      , "    else if (pudu_xml_starts(&in, at, \"<!--\")) at = pudu_xml_past(&in, at, \"-->\");"
      , "    else return NULL;"
      , "    if (at == 0) return NULL;"
      , "  }"
      , "  at = pudu_xml_space(&in, at);"
      , "  if (at >= in.size || !pudu_xml_element(&in, at, 1, NULL, &next)) return NULL;"
      , "  (void)pudu_xml_element(&in, at, 1, &made, &next);"
      , "  return made;"
      , "}"
      ])
  ]
